// Define color gradient
const colors = [
  '#0a1929', // deep blue
  '#1a3a5a', // deeper blue
  '#2a5a7a', // even deeper blue
  '#3a7a9a', // very deep blue
  '#4a9abb', // sky blue
  '#5aaebc'  // lighter blue
];

// Draw spiral
let angle = 0;
let radius = 0;
const steps = 100;

for (let i = 0; i < steps; i++) {
  const r = radius + i * 2;
  const x = centerX + Math.cos(angle) * r;
  const y = centerY + Math.sin(angle) * r;

  // Calculate color based on radius
  const colorIndex = Math.floor((r / maxRadius) * 5);
  const color = colors[colorIndex % colors.length];

  // Draw arc segment
  if (i === 0) {
    ctx.beginPath();
    ctx.moveTo(x, y);
  } else {
    ctx.lineTo(x, y);
  }

  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Alternate between solid and dashed lines
  if (i % 2 === 0) {
    ctx.stroke();
  } else {
    ctx.setLineDash([4, 4]);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // Update angle and radius
  angle += 0.3;
  radius += 0.5;
}

