ctx.stroke();
ctx.beginPath();
ctx.moveTo(240, 270);
ctx.lineTo(250, 290);
ctx.stroke();

// Shell spiral
ctx.fillStyle = '#8B4513';
ctx.beginPath();
let radius = 0;
for (let i = 0; i < 20; i++) {
    const angle = (i / 10) * Math.PI;
    const x = 200 + Math.cos(angle) * radius;
    const y = 250 + Math.sin(angle) * radius;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
    radius += 5;
}
ctx.closePath();
ctx.fill();

// Shell details
ctx.fillStyle = '#A0522D';
for (let i = 0; i < 15; i++) {
    const angle = (i / 15) * Math.PI;
    const x = 200 + Math.cos(angle) * (radius - 3);
    const y = 250 + Math.sin(angle) * (radius - 3);
    ctx.beginPath();
    ctx.arc(x, y, 2, 0, Math.PI * 2);
    ctx.fill();
}

// Shell spiral lines
ctx.strokeStyle = '#C0C0C0';
ctx.lineWidth = 1;
for (let i = 0; i < 20; i++) {
    const angle = (i / 10) * Math.PI;
    const x1 = 200 + Math.cos(angle) * (radius - 10);
    const y1 = 250 + Math.sin(angle) * (radius - 10);
    const x2 = 200 + Math.cos(angle) * (radius - 5);
    const y2 = 250 + Math.sin(angle) * (radius - 5);
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
}

